{"code": "from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
from pathlib import Path

src = Path('/root/data/workbook.xlsx')
print(f'Loading {src} data_only=False')
wb = load_workbook(src, data_only=False)
print('Sheet names:', wb.sheetnames)

task = wb['Task']
data = wb['Data']

def cell_info(ws, coord):
    c = ws[coord]
    return {
        'coord': coord,
        'value': c.value,
        'fill': c.fill.fgColor.rgb if c.fill and c.fill.fgColor and c.fill.fgColor.type == 'rgb' else (c.fill.fgColor.indexed if c.fill and c.fill.fgColor else None),
        'num_format': c.number_format,
        'style_id': c.style_id,
    }

print('\nTask series codes D12:D17')
for r in range(12,18): print(f'D{r}={task.cell(r,4).value!r}')
print('\nTask series codes D19:D24')
for r in range(19,25): print(f'D{r}={task.cell(r,4).value!r}')
print('\nTask series codes D26:D31')
for r in range(26,32): print(f'D{r}={task.cell(r,4).value!r}')
print('\nTask years row 10 H:L')
for c in range(8,13): print(f'{get_column_letter(c)}10={task.cell(10,c).value!r}')

print('\nTask current H35:L47')
for r in range(35,48):
    vals = [task.cell(r,c).value for c in range(8,13)]
    print(f'row {r}: {vals}')
print('\nTask current H50:L50')
print([task.cell(50,c).value for c in range(8,13)])

print('\nData rows 21-38 (columns with data only)')
for r in range(21,39):
    row_cells=[]
    for c in range(1,data.max_column+1):
        v=data.cell(r,c).value
        if v is not None:
            row_cells.append(f'{get_column_letter(c)}{r}={v!r}')
    print(f'row {r}: ' + ', '.join(row_cells))

print('\nYellow target range content / formatting notes')
for rng in ['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']:
    print(f'Range {rng}:')
    for row in task[rng]:
        pieces=[]
        for c in row:
            fill = c.fill.fgColor.rgb if c.fill and c.fill.fgColor and c.fill.fgColor.type == 'rgb' else (f'indexed:{c.fill.fgColor.indexed}' if c.fill and c.fill.fgColor and c.fill.fgColor.type == 'indexed' else str(c.fill.fgColor.type if c.fill and c.fill.fgColor else None))
            pieces.append(f'{c.coordinate}: value={c.value!r}, fill={fill}, numfmt={c.number_format!r}, style={c.style_id}')
        print('  ' + ' | '.join(pieces))
